int main(int argc, char **argv)
{
	(void)argc; /*Unused*/
	(void)argv; /*Unused*/

#ifdef _WIN32
	SetUnhandledExceptionFilter(crash_handler);
	/* 看门狗（仅模拟器）：独立线程监测主循环心跳，卡死（lv_timer_handler 死循环/渲染卡住）时打印定位日志 */
	g_main_tid = GetCurrentThreadId();
	volatile unsigned int *heartbeat = malloc(sizeof(unsigned int));
	*heartbeat = 0;
	DWORD tid;
	CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)watchdog_proc, (LPVOID)heartbeat, 0, &tid);
#define WATCHDOG_HEARTBEAT() do { *heartbeat = SDL_GetTicks(); } while (0)
#else
#define WATCHDOG_HEARTBEAT() do { } while (0)
#endif

	/*Initialize LVGL*/
	lv_init();

	/*Initialize the HAL (display, input devices, tick) for LVGL*/
    hal_init(1280, 480);
	SDL_AddEventWatch(watchdog_event_feed, heartbeat);   /* 事件喂狗:覆盖窗口拖动/缩放的模态循环 */

	/*Initialize UI*/
    ui_init();

	while(1) {
		WATCHDOG_HEARTBEAT();
		lv_timer_handler();

		/* 读键状态模拟编码器（边沿触发防连击） */
		static uint8_t prev_key = 0;
		static uint8_t prev_door = 0;
		static uint8_t prev_8 = 0, prev_9 = 0, prev_minus = 0, prev_lang = 0, prev_c = 0;
		static uint8_t prev_l = 0;
		static uint8_t prev_e = 0;
		SDL_PumpEvents();
		const Uint8 *keys = SDL_GetKeyboardState(NULL);
		uint8_t sim_key = 0;
		uint8_t cur_door = keys[SDL_SCANCODE_0];
		uint8_t cur_8 = keys[SDL_SCANCODE_8];
		uint8_t cur_9 = keys[SDL_SCANCODE_9];
		uint8_t cur_minus = keys[SDL_SCANCODE_MINUS];
		uint8_t cur_lang = keys[SDL_SCANCODE_6];   /* 6=中英切换（原F8） */
		uint8_t cur_c = keys[SDL_SCANCODE_C];      /* C=烹饪立即完成（调试） */
		uint8_t cur_l = keys[SDL_SCANCODE_L];      /* L=炉灯开/关（模拟电源板发 BUF[14] BIT0） */
		uint8_t cur_e = keys[SDL_SCANCODE_E];      /* E=故障注入/解除（模拟电源板发 BUF[12] 报警序号 0<->3） */
		if      (keys[SDL_SCANCODE_TAB])       sim_key = KEY_MENU;
		else if (keys[SDL_SCANCODE_5])         sim_key = KEY_EXTRA_COLOR;
		else if (keys[SDL_SCANCODE_ESCAPE])    sim_key = KEY_BACK;
		else if (keys[SDL_SCANCODE_RIGHT] ||
		         keys[SDL_SCANCODE_DOWN])   sim_key = KEY_ENCODER_CW;
		else if (keys[SDL_SCANCODE_LEFT]  ||
		         keys[SDL_SCANCODE_UP])     sim_key = KEY_ENCODER_CCW;
		else if (keys[SDL_SCANCODE_SPACE])  sim_key = KEY_ENCODER_PRESS;
		else if (keys[SDL_SCANCODE_1])      sim_key = KEY1;
		else if (keys[SDL_SCANCODE_2])      sim_key = KEY_SIXMENU;
		else if (keys[SDL_SCANCODE_4])      sim_key = KEY_PREHEAT;
		else if (keys[SDL_SCANCODE_7])      sim_key = KEY_CLEAN;
		else if (keys[SDL_SCANCODE_3])      sim_key = KEY_FAV;
		else if (keys[SDL_SCANCODE_F9])     sim_key = KEY_SET;
		if (cur_8 && !prev_8) {
			uart_data_receive[Receive_data_Probe_Temp_L] += 5;
			printf("[sim] probe temp +=5 -> %d\n",
				((uint16_t)uart_data_receive[Receive_data_Probe_Temp_H] << 8) | uart_data_receive[Receive_data_Probe_Temp_L]);
		}
		if (cur_9 && !prev_9) {
			uart_data_receive[Receive_data_Power_ALL_State] ^= (1 << 2);
			printf("[sim] probe %s\n",
				(uart_data_receive[Receive_data_Power_ALL_State] & (1 << 2)) ? "INSERTED" : "REMOVED");
		}
		if (cur_minus && !prev_minus) {
			if (uart_data_receive[Receive_data_Probe_Temp_L] >= 5)
				uart_data_receive[Receive_data_Probe_Temp_L] -= 5;
			printf("[sim] probe temp -=5 -> %d\n",
				((uint16_t)uart_data_receive[Receive_data_Probe_Temp_H] << 8) | uart_data_receive[Receive_data_Probe_Temp_L]);
		}
		prev_8 = cur_8; prev_9 = cur_9; prev_minus = cur_minus;

		if (cur_lang && !prev_lang) {
			/* 语言循环 简→英→繁→简(测试键): EN/繁走树遍历刷新, 回简体靠翻页重建 */
			SET_Data.Set_Language = (SET_Data.Set_Language + 1) % 3;
			g_lang_en = (SET_Data.Set_Language == 0) ? 1 : 0;
			extern void lang_on_page_built(void);
			lang_on_page_built();
			printf("[sim] lang %s\n", SET_Data.Set_Language == 0 ? "EN" :
			       (SET_Data.Set_Language == 1 ? "TW(繁體)" : "CN(简体)"));
		}
		prev_lang = cur_lang;
		if (cur_door && !prev_door) {
			uart_data_receive[Receive_data_Power_ALL_State] ^= (1 << 1);
			printf("[sim] door %s\n",
				(uart_data_receive[Receive_data_Power_ALL_State] & (1 << 1)) ? "OPEN" : "CLOSED");
		}
		prev_door = cur_door;

		if (cur_l && !prev_l) {
			uart_data_receive[Receive_data_Power_ALL_State2] ^= (1 << 0);
			printf("[sim] lamp %s\n",
				(uart_data_receive[Receive_data_Power_ALL_State2] & (1 << 0)) ? "ON" : "OFF");
			extern void nav_topflag_demo_sync(void);
			nav_topflag_demo_sync();   /* 立即显/隐 light 图标,不等 500ms tick */
		}
		prev_l = cur_l;

		if (cur_c && !prev_c) {
			extern void sim_force_cook_done(void);
			sim_force_cook_done();
		}
		prev_c = cur_c;

		if (cur_e && !prev_e) {
			uart_data_receive[Receive_data_Power_ALL_Error] =
				uart_data_receive[Receive_data_Power_ALL_Error] ? 0 : 3;   /* 注入 E-3/解除 */
			printf("[sim] alarm %s (BUF[12]=%d)\n",
				uart_data_receive[Receive_data_Power_ALL_Error] ? "INJECT E-3" : "CLEARED",
				uart_data_receive[Receive_data_Power_ALL_Error]);
		}
		prev_e = cur_e;

		if (sim_key != prev_key) {
			nav_handle_key(sim_key);
			prev_key = sim_key;
		}

		usleep(5 * 1000);
	}

	return 0;
}

